#!/usr/bin/env python3
"""
Fraud analysis script for invoices
"""
import json
import re
from typing import List, Dict, Optional, Tuple
from difflib import SequenceMatcher
import pandas as pd
from pypdf import PdfReader
import csv

def fuzzy_match(str1: str, str2: str, threshold: float = 0.85) -> bool:
    """Check if two strings are similar enough using fuzzy matching"""
    ratio = SequenceMatcher(None, str1.lower(), str2.lower()).ratio()
    return ratio >= threshold

def extract_invoices_from_pdf(pdf_path: str) -> List[Dict]:
    """Extract invoice data from PDF"""
    invoices = []
    reader = PdfReader(pdf_path)

    for page_num, page in enumerate(reader.pages, 1):
        text = page.extract_text()
        invoice = parse_invoice_text(text, page_num)
        if invoice:
            invoices.append(invoice)

    return invoices

def parse_invoice_text(text: str, page_num: int) -> Optional[Dict]:
    """Parse invoice text from a page"""
    invoice = {
        'page_number': page_num,
        'vendor_name': None,
        'invoice_amount': None,
        'iban': None,
        'po_number': None
    }

    # Extract Vendor Name (look for common patterns)
    vendor_match = re.search(r'(?:Vendor|Company|From|Supplier)[\s:]+([^\n]+)', text, re.IGNORECASE)
    if vendor_match:
        invoice['vendor_name'] = vendor_match.group(1).strip()

    # Extract Invoice Amount (look for currency amounts)
    # Matches patterns like $1234.56, EUR 1234.56, 1234.56 EUR, etc.
    amount_pattern = r'(?:Amount|Total|Invoice\s+Amount)[\s:]+(?:€|EUR|\$|USD)?[\s]*([0-9]+(?:[.,][0-9]{2})?)'
    amount_match = re.search(amount_pattern, text, re.IGNORECASE)
    if amount_match:
        amount_str = amount_match.group(1).replace(',', '.')
        try:
            invoice['invoice_amount'] = float(amount_str)
        except ValueError:
            pass

    # Extract IBAN
    iban_match = re.search(r'(?:IBAN|Account)[\s:]+([A-Z]{2}[0-9]{2}[A-Z0-9]+)', text)
    if iban_match:
        invoice['iban'] = iban_match.group(1).strip()

    # Extract PO Number
    po_match = re.search(r'(?:PO\s+Number|Purchase\s+Order|PO#?)[\s:]+([A-Z0-9\-]+)', text, re.IGNORECASE)
    if po_match:
        invoice['po_number'] = po_match.group(1).strip()

    return invoice

def extract_vendors_from_xlsx(xlsx_path: str) -> List[Dict]:
    """Extract vendor data from Excel file"""
    df = pd.read_excel(xlsx_path)
    vendors = []

    for _, row in df.iterrows():
        vendor = {
            'vendor_id': str(row.get('Vendor ID', '')).strip(),
            'name': str(row.get('Name', '')).strip(),
            'iban': str(row.get('IBAN', '')).strip()
        }
        vendors.append(vendor)

    return vendors

def extract_purchase_orders_from_csv(csv_path: str) -> List[Dict]:
    """Extract purchase order data from CSV"""
    purchase_orders = []

    with open(csv_path, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            po = {
                'po_number': row.get('PO Number', '').strip(),
                'amount': float(row.get('Amount', 0)),
                'vendor_id': row.get('Vendor ID', '').strip()
            }
            purchase_orders.append(po)

    return purchase_orders

def check_fraud(invoice: Dict, vendors: List[Dict], purchase_orders: List[Dict]) -> Optional[Tuple[str, str]]:
    """
    Check invoice against fraud criteria
    Returns tuple of (reason, details) or None if no fraud detected
    """

    # Create lookup dictionaries for faster access
    vendors_by_name = {v['name']: v for v in vendors}
    vendors_by_id = {v['vendor_id']: v for v in vendors}
    po_by_number = {po['po_number']: po for po in purchase_orders}

    vendor_name = invoice.get('vendor_name', '').strip()
    invoice_amount = invoice.get('invoice_amount')
    iban = invoice.get('iban', '').strip()
    po_number = invoice.get('po_number')

    # Criterion 1: Unknown Vendor
    matching_vendor = None
    for vendor in vendors:
        if fuzzy_match(vendor_name, vendor['name']):
            matching_vendor = vendor
            break

    if not matching_vendor:
        return ("Unknown Vendor", f"Vendor '{vendor_name}' not found in vendor list")

    # Criterion 2: IBAN Mismatch
    if iban and matching_vendor['iban']:
        if iban != matching_vendor['iban']:
            return ("IBAN Mismatch", f"Invoice IBAN {iban} doesn't match vendor IBAN {matching_vendor['iban']}")

    # Criterion 3 & 4 & 5: PO-related checks (only if PO number exists)
    if po_number:
        # Criterion 3: Invalid PO
        matching_po = po_by_number.get(po_number)
        if not matching_po:
            return ("Invalid PO", f"PO number '{po_number}' not found in purchase orders")

        # Criterion 4: Amount Mismatch
        if invoice_amount is not None and matching_po['amount'] is not None:
            if abs(invoice_amount - matching_po['amount']) > 0.01:
                return ("Amount Mismatch", f"Invoice amount {invoice_amount} doesn't match PO amount {matching_po['amount']}")

        # Criterion 5: Vendor Mismatch
        if matching_po['vendor_id'] != matching_vendor['vendor_id']:
            return ("Vendor Mismatch", f"PO is linked to vendor {matching_po['vendor_id']}, but invoice is from {matching_vendor['vendor_id']}")

    return None

def main():
    print("Extracting data from files...")

    # Extract data
    invoices = extract_invoices_from_pdf('/root/invoices.pdf')
    vendors = extract_vendors_from_xlsx('/root/vendors.xlsx')
    purchase_orders = extract_purchase_orders_from_csv('/root/purchase_orders.csv')

    print(f"Extracted {len(invoices)} invoices")
    print(f"Extracted {len(vendors)} vendors")
    print(f"Extracted {len(purchase_orders)} purchase orders")

    # Debug: print first invoice
    if invoices:
        print(f"\nFirst invoice: {invoices[0]}")

    # Analyze for fraud
    fraud_report = []

    for invoice in invoices:
        fraud_result = check_fraud(invoice, vendors, purchase_orders)

        if fraud_result:
            reason, _ = fraud_result
            fraud_item = {
                'invoice_page_number': invoice['page_number'],
                'vendor_name': invoice.get('vendor_name'),
                'invoice_amount': invoice.get('invoice_amount'),
                'iban': invoice.get('iban'),
                'po_number': invoice.get('po_number'),
                'reason': reason
            }
            fraud_report.append(fraud_item)
            print(f"Page {invoice['page_number']}: {reason}")

    # Save results
    with open('/root/fraud_report.json', 'w') as f:
        json.dump(fraud_report, f, indent=2)

    print(f"\nFraud analysis complete. Found {len(fraud_report)} fraudulent invoices.")
    print(f"Report saved to /root/fraud_report.json")

if __name__ == '__main__':
    main()

